// Goal handling: accept/reject, cancel, emergency stop, reset, result codes.
// Every test starts with the node ACTIVE and IDLE (see mission_fixture.hpp).
//
// Pattern used in every test:
//   1. Arrange : set up the mock / state the test needs
//   2. Act     : send the goal / call the service
//   3. Assert  : check result code, goal status and state
// ASSERT_* stops the test on failure (use for preconditions).
// EXPECT_* records the failure and continues (use for the actual checks).

#include "mission_fixture.hpp"

using positronic_mission::GoToPose;
using positronic_mission::MotionOutcome;
using positronic_mission::State;
using rclcpp_action::ResultCode;

namespace positronic_mission::test
{

// ======================= Execution =======================

TEST_F(MissionNodeTest, GoalSucceedsWhenIdle)
{
  auto handle = send_goal(valid_pose());
  ASSERT_NE(handle, nullptr) << "Goal was rejected";

  auto result = wait_result(handle);
  ASSERT_TRUE(result.has_value()) << "No result";

  EXPECT_EQ(result->code, ResultCode::SUCCEEDED);
  EXPECT_EQ(result->result->code, GoToPose::Result::OK);
  EXPECT_TRUE(result->result->success);
  EXPECT_TRUE(wait_until([this] {
      return feedback_count_ > 0;
  }))
    << "No feedback received";
  EXPECT_TRUE(wait_for_state(State::IDLE));
  EXPECT_EQ(mock_->calls, 1);
}

TEST_F(MissionNodeTest, TwoGoalsInARowBothSucceed)
{
  for (int i = 0; i < 2; ++i) {
    auto handle = send_goal(valid_pose());
    ASSERT_NE(handle, nullptr) << "Goal " << i << " rejected";
    auto result = wait_result(handle);
    ASSERT_TRUE(result.has_value());
    EXPECT_EQ(result->result->code, GoToPose::Result::OK);
    ASSERT_TRUE(wait_for_state(State::IDLE));
  }
  EXPECT_EQ(mock_->calls, 2);
}

// ======================= Rejection =======================

TEST_F(MissionNodeTest, RejectsInvalidFrame)
{
  auto pose = valid_pose();
  pose.header.frame_id = "world";

  EXPECT_EQ(send_goal(pose), nullptr);
  EXPECT_EQ(mock_->calls, 0);
  EXPECT_TRUE(wait_for_state(State::IDLE));
}

TEST_F(MissionNodeTest, RejectsGoalWhileMoving)
{
  mock_->duration_ms = 1000;
  auto first = send_goal(valid_pose());
  ASSERT_NE(first, nullptr);
  ASSERT_TRUE(wait_for_state(State::MOVING));

  // Second goal: rejected, never queued
  EXPECT_EQ(send_goal(valid_pose()), nullptr);

  // The first goal is unaffected
  auto result = wait_result(first);
  ASSERT_TRUE(result.has_value());
  EXPECT_EQ(result->result->code, GoToPose::Result::OK);
  EXPECT_EQ(mock_->calls, 1);
}

TEST_F(MissionNodeTest, RejectsGoalWhenInactive)
{
  ASSERT_EQ(node_->deactivate().id(), lifecycle_msgs::msg::State::PRIMARY_STATE_INACTIVE);

  EXPECT_EQ(send_goal(valid_pose()), nullptr);
  EXPECT_EQ(mock_->calls, 0);
}

// ======================= Cancellation =======================

TEST_F(MissionNodeTest, CancelMidGoalGivesCanceledAndStopped)
{
  mock_->duration_ms = 2000;
  auto handle = send_goal(valid_pose());
  ASSERT_NE(handle, nullptr);
  ASSERT_TRUE(wait_for_state(State::MOVING));

  ASSERT_TRUE(cancel_goal(handle));

  auto result = wait_result(handle);
  ASSERT_TRUE(result.has_value());
  EXPECT_EQ(result->code, ResultCode::CANCELED);
  EXPECT_EQ(result->result->code, GoToPose::Result::CANCELED);
  EXPECT_FALSE(result->result->success);
  EXPECT_TRUE(wait_for_state(State::STOPPED));
}

TEST_F(MissionNodeTest, AfterCancelGoalsRejectedUntilReset)
{
  mock_->duration_ms = 2000;
  auto handle = send_goal(valid_pose());
  ASSERT_NE(handle, nullptr);
  ASSERT_TRUE(wait_for_state(State::MOVING));
  ASSERT_TRUE(cancel_goal(handle));
  ASSERT_TRUE(wait_result(handle).has_value());
  ASSERT_TRUE(wait_for_state(State::STOPPED));

  // Rejected while STOPPED
  EXPECT_EQ(send_goal(valid_pose()), nullptr);

  // Reset -> IDLE -> accepted again
  auto reset = call_reset();
  ASSERT_NE(reset, nullptr);
  EXPECT_TRUE(reset->accepted);
  ASSERT_TRUE(wait_for_state(State::IDLE));

  mock_->duration_ms = 100;
  auto next = send_goal(valid_pose());
  ASSERT_NE(next, nullptr);
  auto result = wait_result(next);
  ASSERT_TRUE(result.has_value());
  EXPECT_EQ(result->result->code, GoToPose::Result::OK);
}

// ======================= Emergency stop =======================

TEST_F(MissionNodeTest, EStopMidGoalAbortsWithStopped)
{
  mock_->duration_ms = 2000;
  auto handle = send_goal(valid_pose());
  ASSERT_NE(handle, nullptr);
  ASSERT_TRUE(wait_for_state(State::MOVING));

  auto stop = call_stop();
  ASSERT_NE(stop, nullptr);
  EXPECT_TRUE(stop->accepted);

  auto result = wait_result(handle);
  ASSERT_TRUE(result.has_value());
  EXPECT_EQ(result->code, ResultCode::ABORTED);
  EXPECT_EQ(result->result->code, GoToPose::Result::STOPPED);
  EXPECT_TRUE(wait_for_state(State::STOPPED));
  EXPECT_GE(mock_->stops, 1);
}

TEST_F(MissionNodeTest, EStopWhileIdleBlocksGoalsUntilReset)
{
  auto stop = call_stop();
  ASSERT_NE(stop, nullptr);
  EXPECT_TRUE(stop->accepted);
  ASSERT_TRUE(wait_for_state(State::STOPPED));

  EXPECT_EQ(send_goal(valid_pose()), nullptr);
  EXPECT_EQ(mock_->calls, 0);

  auto reset = call_reset();
  ASSERT_NE(reset, nullptr);
  EXPECT_TRUE(reset->accepted);
  EXPECT_TRUE(wait_for_state(State::IDLE));
}

// An old stop must not preempt the next goal: handle_goal calls reset_stop()
TEST_F(MissionNodeTest, OldStopDoesNotPreemptNextGoal)
{
  ASSERT_NE(call_stop(), nullptr);
  ASSERT_TRUE(wait_for_state(State::STOPPED));
  ASSERT_NE(call_reset(), nullptr);
  ASSERT_TRUE(wait_for_state(State::IDLE));

  auto handle = send_goal(valid_pose());
  ASSERT_NE(handle, nullptr);
  auto result = wait_result(handle);
  ASSERT_TRUE(result.has_value());
  EXPECT_EQ(result->result->code, GoToPose::Result::OK) << "Stale stop preempted the goal";
}

TEST_F(MissionNodeTest, EStopDuringErrorKeepsError)
{
  // Arrange: get the node into ERROR through a failed execution
  mock_->outcome = MotionOutcome::EXECUTION_FAILED;
  auto handle = send_goal(valid_pose());
  ASSERT_NE(handle, nullptr);
  auto result = wait_result(handle);
  ASSERT_TRUE(result.has_value());
  EXPECT_EQ(result->code, ResultCode::ABORTED);
  EXPECT_EQ(result->result->code, GoToPose::Result::ERROR);
  ASSERT_TRUE(wait_for_state(State::ERROR));

  // Act: e-stop is accepted, but ERROR is kept
  auto stop = call_stop();
  ASSERT_NE(stop, nullptr);
  EXPECT_TRUE(stop->accepted);
  EXPECT_TRUE(wait_for_state(State::ERROR));

  // Reset still works afterwards
  auto reset = call_reset();
  ASSERT_NE(reset, nullptr);
  EXPECT_TRUE(reset->accepted);
  EXPECT_TRUE(wait_for_state(State::IDLE));
}

// ======================= Reset =======================

TEST_F(MissionNodeTest, ResetRefusedWhenIdle)
{
  auto reset = call_reset();
  ASSERT_NE(reset, nullptr);
  EXPECT_FALSE(reset->accepted);
  EXPECT_TRUE(wait_for_state(State::IDLE));
}

TEST_F(MissionNodeTest, ResetRefusedWhileMoving)
{
  mock_->duration_ms = 1000;
  auto handle = send_goal(valid_pose());
  ASSERT_NE(handle, nullptr);
  ASSERT_TRUE(wait_for_state(State::MOVING));

  auto reset = call_reset();
  ASSERT_NE(reset, nullptr);
  EXPECT_FALSE(reset->accepted);

  // The goal still finishes normally
  auto result = wait_result(handle);
  ASSERT_TRUE(result.has_value());
  EXPECT_EQ(result->result->code, GoToPose::Result::OK);
}
}  // namespace positronic_mission::test
